import sys

def min_lexicographic_string(n, k, s):
    s = list(s)
    swaps = 0
    for i in range(n):
        for j in range(1, n - i):
            if s[j] < s[j - 1]:
                s[j], s[j - 1] = s[j - 1], s[j]
                swaps += 1
                if swaps == k:
                    return ''.join(s)
    return ''.join(s)

def main():
    import sys
